</main><script>
document.querySelectorAll('.question-form').forEach(form=>{const type=form.querySelector('.question-type');const refresh=()=>{const value=type.value;form.querySelector('.choice-fields').style.display=['opcion_unica','seleccion_multiple'].includes(value)?'block':'none';form.querySelectorAll('.unique-check').forEach(el=>el.style.display=value==='opcion_unica'?'block':'none');form.querySelectorAll('.multiple-check').forEach(el=>el.style.display=value==='seleccion_multiple'?'block':'none');form.querySelector('.boolean-fields').style.display=value==='verdadero_falso'?'block':'none';form.querySelector('.written-fields').style.display=value==='respuesta_directa'?'block':'none'};type.addEventListener('change',refresh);refresh()});
</script></body></html>


